import{_ as s,c as a,d as e,o as l}from"./app-AF038EZb.js";const i={};function p(t,n){return l(),a("div",null,[...n[0]||(n[0]=[e(`<h1 id="langchain-基础" tabindex="-1"><a class="header-anchor" href="#langchain-基础"><span>LangChain 基础</span></a></h1><h2 id="_1-1-什么是-langchain" tabindex="-1"><a class="header-anchor" href="#_1-1-什么是-langchain"><span>1.1 什么是 LangChain</span></a></h2><p>随着大语言模型（Large Language Model，LLM）的快速发展，越来越多的软件系统开始接入 AI 能力，例如智能客服、企业知识库、AI 助手、自动化办公工具等。但是，大语言模型本身只负责理解用户输入并生成文本，它并不了解企业内部数据，也无法直接访问数据库、调用业务接口或执行具体任务。</p><p>例如，一个企业希望开发一个内部知识库问答系统，员工询问“公司的报销流程是什么”。如果直接调用大模型，模型并不知道企业自己的规章制度，因此无法给出准确答案。要解决这个问题，需要在用户问题和大模型之间增加一层应用逻辑，将企业数据、业务工具以及模型能力结合起来。</p><p>LangChain 就是在这种背景下产生的。它是一个用于构建大语言模型应用的开发框架，提供了模型调用、Prompt 管理、流程编排、数据检索、工具调用以及 Agent 构建等能力，帮助开发者更加方便地开发基于 LLM 的应用。(<a href="https://docs.langchain.com/oss/python/langchain/overview?utm_source=chatgpt.com" target="_blank" rel="noopener noreferrer">Docs by LangChain</a>)</p><p>简单理解，LangChain 不是一个新的大模型，而是连接业务系统和大模型之间的应用开发框架。</p><p>传统的大模型调用流程通常比较简单：</p><p>用户输入问题 → 调用模型 API → 返回模型结果。</p><p>而实际业务中的 AI 应用通常需要更复杂的流程：</p><p>用户输入问题 → 业务系统处理 → 查询相关数据 → 调用大模型分析 → 调用工具执行任务 → 返回最终结果。</p><p>LangChain 主要负责中间这一层，将多个 AI 能力组合成完整的应用流程。</p><hr><h2 id="_1-2-为什么需要-langchain" tabindex="-1"><a class="header-anchor" href="#_1-2-为什么需要-langchain"><span>1.2 为什么需要 LangChain</span></a></h2><p>如果只是实现简单的文本生成或聊天功能，直接调用 OpenAI、Claude、DeepSeek 等模型 API 即可。但是在企业级应用中，AI 通常需要结合业务数据和外部能力，例如：</p><ul><li>根据企业文档回答问题。</li><li>根据数据库数据生成分析结果。</li><li>根据用户需求调用第三方接口。</li><li>根据任务自动选择执行步骤。</li><li>保存用户历史对话。</li></ul><p>这些功能如果全部自行实现，需要开发者处理大量基础逻辑，包括：</p><ul><li>模型接口封装。</li><li>Prompt 管理。</li><li>上下文维护。</li><li>文档解析。</li><li>向量检索。</li><li>工具调用。</li><li>多步骤任务流程控制。</li></ul><p>LangChain 对这些常见能力进行了抽象，使开发者可以通过统一接口快速构建 AI 应用。它目前提供了丰富的模型、工具、向量数据库以及数据处理组件集成能力。(<a href="https://docs.langchain.com/oss/python/integrations/providers/overview?utm_source=chatgpt.com" target="_blank" rel="noopener noreferrer">Docs by LangChain</a>)</p><p>例如，一个 AI 简历优化助手的实现流程：</p><p>用户上传简历 → 系统解析简历内容 → 检索岗位要求 → 调用大模型分析 → 生成优化建议。</p><p>其中：</p><ul><li>FastAPI 负责接收文件上传请求。</li><li>LangChain 负责组织 AI 处理流程。</li><li>大语言模型负责理解和生成内容。</li><li>数据库负责保存用户信息和历史记录。</li></ul><p>通过这种分层设计，可以让 AI 能力更容易融入已有的软件系统。</p><hr><h2 id="_1-3-langchain-在-ai-应用开发中的位置" tabindex="-1"><a class="header-anchor" href="#_1-3-langchain-在-ai-应用开发中的位置"><span>1.3 LangChain 在 AI 应用开发中的位置</span></a></h2><p>一个完整的 AI 应用通常可以分为多个层次：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">前端层</span>
<span class="line">Vue / React</span>
<span class="line"></span>
<span class="line">        ↓</span>
<span class="line"></span>
<span class="line">接口层</span>
<span class="line">FastAPI</span>
<span class="line"></span>
<span class="line">        ↓</span>
<span class="line"></span>
<span class="line">业务层</span>
<span class="line">用户管理</span>
<span class="line">权限控制</span>
<span class="line">文件处理</span>
<span class="line"></span>
<span class="line">        ↓</span>
<span class="line"></span>
<span class="line">AI 应用层</span>
<span class="line">LangChain</span>
<span class="line"></span>
<span class="line">        ↓</span>
<span class="line"></span>
<span class="line">模型层</span>
<span class="line">GPT</span>
<span class="line">Claude</span>
<span class="line">Gemini</span>
<span class="line">DeepSeek</span>
<span class="line"></span>
<span class="line">        ↓</span>
<span class="line"></span>
<span class="line">数据层</span>
<span class="line">MySQL</span>
<span class="line">Redis</span>
<span class="line">向量数据库</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在这个架构中，各部分职责不同。</p><p>FastAPI 主要负责 Web 服务相关逻辑，例如：</p><ul><li>接收 HTTP 请求。</li><li>参数校验。</li><li>用户身份认证。</li><li>返回接口响应。</li></ul><p>LangChain 负责 AI 应用逻辑，例如：</p><ul><li>组织 Prompt。</li><li>调用模型。</li><li>查询知识库。</li><li>调用外部工具。</li><li>管理 Agent 流程。</li></ul><p>大语言模型负责：</p><ul><li>理解自然语言。</li><li>进行推理。</li><li>生成文本结果。</li></ul><p>因此，在实际项目中，FastAPI 和 LangChain 通常是配合使用的：</p><p>FastAPI 作为后端服务入口，LangChain 作为 AI 能力编排层。</p><hr><h2 id="_1-4-langchain-核心组成" tabindex="-1"><a class="header-anchor" href="#_1-4-langchain-核心组成"><span>1.4 LangChain 核心组成</span></a></h2><p>LangChain 的设计思想是将复杂的 AI 应用拆分为多个可以组合的模块。目前常用的核心组件包括 Model、Prompt、Chain、Retriever 和 Agent 等。(<a href="https://reference.langchain.com/python/langchain/overview?utm_source=chatgpt.com" target="_blank" rel="noopener noreferrer">LangChain 参考文档</a>)</p><h3 id="_1-4-1-model-模型" tabindex="-1"><a class="header-anchor" href="#_1-4-1-model-模型"><span>1.4.1 Model（模型）</span></a></h3><p>Model 是 LangChain 中负责调用大语言模型的组件。</p><p>不同模型厂商通常提供不同的 API，例如：</p><ul><li>OpenAI 提供 GPT 系列模型。</li><li>Anthropic 提供 Claude 系列模型。</li><li>Google 提供 Gemini 系列模型。</li><li>国内厂商提供 DeepSeek、通义千问等模型。</li></ul><p>不同模型的调用方式存在差异，而 LangChain 对这些模型进行了统一封装，使开发者可以使用类似的方式调用不同模型。</p><p>例如：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">response <span class="token operator">=</span> llm<span class="token punctuation">.</span>invoke<span class="token punctuation">(</span><span class="token string">&quot;介绍一下 FastAPI&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>开发者不需要关心底层具体调用的是哪一家模型，只需要通过 LangChain 提供的接口完成调用即可。</p><hr><h3 id="_1-4-2-prompt-提示词" tabindex="-1"><a class="header-anchor" href="#_1-4-2-prompt-提示词"><span>1.4.2 Prompt（提示词）</span></a></h3><p>Prompt 是发送给大模型的输入内容。</p><p>大模型最终生成什么结果，很大程度取决于 Prompt 的设计。</p><p>例如：</p><p>普通问题：</p><p>“介绍一下 React。”</p><p>优化后的 Prompt：</p><p>“你是一名前端高级工程师，请从核心原理、使用场景和代码示例三个方面介绍 React。”</p><p>后者能够更加明确地限制模型输出方向。</p><p>在实际项目中，Prompt 通常不会直接写死，而是使用模板管理，例如：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">请回答下面的问题：</span>
<span class="line"></span>
<span class="line">{question}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>运行时再动态替换变量。</p><p>这样可以实现：</p><ul><li>Prompt 与业务代码分离。</li><li>统一管理提示词。</li><li>方便后续优化模型效果。</li></ul><hr><h3 id="_1-4-3-chain-链" tabindex="-1"><a class="header-anchor" href="#_1-4-3-chain-链"><span>1.4.3 Chain（链）</span></a></h3><p>Chain 表示多个处理步骤的组合。</p><p>一个简单的 AI 问答流程可以表示为：</p><p>用户问题 → Prompt 模板处理 → 调用模型 → 返回结果。</p><p>在 LangChain 中，可以将多个组件连接成一个 Chain：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">chain <span class="token operator">=</span> prompt <span class="token operator">|</span> llm</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>其中 <code>|</code> 表示将前一个组件的输出传递给后一个组件。</p><p>通过 Chain，可以将复杂流程拆分为多个简单模块，然后按照业务需求组合。</p><p>例如：</p><p>文档问答流程：</p><p>用户问题 → 文档检索 → Prompt 拼接 → 模型生成答案。</p><hr><h3 id="_1-4-4-retriever-检索器" tabindex="-1"><a class="header-anchor" href="#_1-4-4-retriever-检索器"><span>1.4.4 Retriever（检索器）</span></a></h3><p>Retriever 是 RAG（Retrieval Augmented Generation，检索增强生成）的核心组件。</p><p>由于大模型并不知道企业内部数据，因此需要先从外部数据源中检索相关内容，再交给模型生成答案。</p><p>例如：</p><p>用户：</p><p>“公司的年假政策是什么？”</p><p>系统流程：</p><p>用户问题 → 查询企业文档 → 找到相关内容 → 发送给模型 → 生成回答。</p><p>Retriever 负责其中的数据检索部分。</p><p>常见应用场景：</p><ul><li>企业知识库。</li><li>产品文档问答。</li><li>技术文档助手。</li><li>私有数据分析。</li></ul><hr><h3 id="_1-4-5-agent-智能代理" tabindex="-1"><a class="header-anchor" href="#_1-4-5-agent-智能代理"><span>1.4.5 Agent（智能代理）</span></a></h3><p>Agent 是 LangChain 中用于构建智能任务执行系统的组件。</p><p>普通 Chain 的流程通常是固定的：</p><p>步骤 A → 步骤 B → 步骤 C。</p><p>而 Agent 可以根据用户需求动态决定下一步操作。</p><p>例如用户输入：“查询成都今天的天气。”</p><p>Agent 可以：</p><ol><li>分析用户需求。</li><li>判断需要调用天气接口。</li><li>执行工具调用。</li><li>根据结果生成回复。</li></ol><p>因此 Agent 更适合处理复杂任务，例如：</p><ul><li>AI 助手。</li><li>数据分析助手。</li><li>自动化办公工具。</li><li>多工具调用系统。</li></ul><hr><h2 id="_1-5-langchain-与大模型-api-的关系" tabindex="-1"><a class="header-anchor" href="#_1-5-langchain-与大模型-api-的关系"><span>1.5 LangChain 与大模型 API 的关系</span></a></h2><p>LangChain 和 OpenAI API 并不是替代关系，而是上下层关系。</p><p>大模型 API 提供的是模型能力，例如：</p><p>输入文本 → 返回生成结果。</p><p>LangChain 提供的是应用开发能力，例如：</p><p>用户请求 → 判断任务 → 查询数据 → 调用模型 → 调用工具 → 返回结果。</p><p>可以理解为：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">AI 应用</span>
<span class="line"></span>
<span class="line">    ↓</span>
<span class="line"></span>
<span class="line">LangChain</span>
<span class="line"></span>
<span class="line">    ↓</span>
<span class="line"></span>
<span class="line">大语言模型 API</span>
<span class="line"></span>
<span class="line">    ↓</span>
<span class="line"></span>
<span class="line">GPT / Claude / Gemini / DeepSeek</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果项目只是简单调用模型，例如生成文章、聊天问答，直接使用模型 API 即可。</p><p>如果项目需要：</p><ul><li>企业知识库。</li><li>RAG 问答。</li><li>Agent 工作流。</li><li>数据库查询。</li><li>多步骤任务处理。</li></ul><p>则更适合使用 LangChain。</p><hr><h2 id="_1-6-本章总结" tabindex="-1"><a class="header-anchor" href="#_1-6-本章总结"><span>1.6 本章总结</span></a></h2><p>本章主要介绍了 LangChain 的定位和核心概念。</p><p>需要掌握以下几点：</p><ol><li>LangChain 是用于构建大语言模型应用的开发框架，而不是大模型本身。</li><li>FastAPI 负责后端接口和业务逻辑，LangChain 负责 AI 流程编排，大模型负责理解和生成内容。</li><li>LangChain 的核心组件包括 Model、Prompt、Chain、Retriever 和 Agent。</li><li>企业级 AI 应用通常需要结合数据库、向量数据库以及后端框架共同开发。</li></ol><h1 id="第二章-langchain-开发环境搭建" tabindex="-1"><a class="header-anchor" href="#第二章-langchain-开发环境搭建"><span>第二章 LangChain 开发环境搭建</span></a></h1><h2 id="_2-1-python-环境准备" tabindex="-1"><a class="header-anchor" href="#_2-1-python-环境准备"><span>2.1 Python 环境准备</span></a></h2><p>LangChain 基于 Python 开发，因此在开始使用之前需要准备 Python 开发环境。建议使用 Python 3.10 及以上版本，目前主流 AI 应用项目通常使用 Python 3.10 或 Python 3.11。</p><p>可以通过以下命令查看当前 Python 版本：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">python <span class="token parameter variable">--version</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>如果需要创建独立环境，推荐使用虚拟环境隔离项目依赖。</p><p>使用 venv 创建虚拟环境：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">python <span class="token parameter variable">-m</span> venv .venv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>激活虚拟环境：</p><p>Windows：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">.venv<span class="token punctuation">\\</span>Scripts<span class="token punctuation">\\</span>activate</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Linux / macOS：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token builtin class-name">source</span> .venv/bin/activate</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>在实际开发中，也可以使用 Conda 或 uv 管理 Python 环境。对于 AI 应用开发项目，推荐使用 uv，因为它相比传统 pip 具有更快的依赖解析和安装速度，同时能够更方便地管理项目依赖。</p><p>例如创建项目：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">uv init langchain-demo</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>进入项目目录：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token builtin class-name">cd</span> langchain-demo</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>安装依赖：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">uv <span class="token function">add</span> langchain langchain-openai fastapi uvicorn python-dotenv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><hr><h2 id="_2-2-创建-langchain-项目" tabindex="-1"><a class="header-anchor" href="#_2-2-创建-langchain-项目"><span>2.2 创建 LangChain 项目</span></a></h2><p>一个实际的 LangChain 应用通常不会将所有代码写在一个文件中，而是按照功能进行拆分。</p><p>一个基础项目结构如下：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">langchain-demo</span>
<span class="line"></span>
<span class="line">├── app</span>
<span class="line">│   ├── main.py          # FastAPI入口</span>
<span class="line">│   ├── llm.py           # 大模型配置</span>
<span class="line">│   ├── prompt.py        # Prompt模板</span>
<span class="line">│   ├── chain.py         # LangChain流程</span>
<span class="line">│   └── config.py        # 项目配置</span>
<span class="line">│</span>
<span class="line">├── .env                 # 环境变量</span>
<span class="line">├── requirements.txt</span>
<span class="line">└── pyproject.toml</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>其中：</p><ul><li><code>main.py</code> 负责启动 FastAPI 服务以及定义接口。</li><li><code>llm.py</code> 负责初始化大模型客户端。</li><li><code>prompt.py</code> 用于集中管理提示词模板。</li><li><code>chain.py</code> 负责组合 LangChain 处理流程。</li><li><code>.env</code> 保存 API Key 等敏感配置。</li></ul><p>这种结构与传统后端项目比较类似，可以方便后续扩展数据库、用户系统以及 RAG 等功能。</p><hr><h2 id="_2-3-安装-langchain-相关依赖" tabindex="-1"><a class="header-anchor" href="#_2-3-安装-langchain-相关依赖"><span>2.3 安装 LangChain 相关依赖</span></a></h2><p>LangChain 本身采用模块化设计，不同功能对应不同 Python 包。</p><p>基础安装：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">pip <span class="token function">install</span> langchain</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>如果需要调用 OpenAI 兼容模型，需要安装：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">pip <span class="token function">install</span> langchain-openai</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>如果使用 FastAPI 构建接口：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">pip <span class="token function">install</span> fastapi uvicorn</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>如果需要读取环境变量：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">pip <span class="token function">install</span> python-dotenv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>完整依赖：</p><div class="language-txt line-numbers-mode" data-highlighter="prismjs" data-ext="txt"><pre><code><span class="line">langchain</span>
<span class="line">langchain-openai</span>
<span class="line">fastapi</span>
<span class="line">uvicorn</span>
<span class="line">python-dotenv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>目前 LangChain 将核心能力和第三方模型连接器进行了拆分，例如：</p><ul><li><code>langchain</code>：核心框架。</li><li><code>langchain-openai</code>：OpenAI 模型支持。</li><li><code>langchain-community</code>：社区维护的各种工具和数据连接组件。</li></ul><p>这种设计可以避免安装大量不需要的依赖。</p><hr><h2 id="_2-4-配置大模型-api" tabindex="-1"><a class="header-anchor" href="#_2-4-配置大模型-api"><span>2.4 配置大模型 API</span></a></h2><p>LangChain 本身不会提供大模型能力，它需要连接具体的大语言模型服务。</p><p>目前常见选择包括：</p><ul><li>OpenAI GPT 系列。</li><li>Anthropic Claude 系列。</li><li>Google Gemini 系列。</li><li>DeepSeek、通义千问等国内模型。</li></ul><p>这些模型大部分提供 OpenAI API 格式兼容接口，因此可以通过统一方式接入。</p><p>项目根目录创建 <code>.env</code> 文件：</p><div class="language-env line-numbers-mode" data-highlighter="prismjs" data-ext="env"><pre><code><span class="line">OPENAI_API_KEY=your_api_key</span>
<span class="line">OPENAI_BASE_URL=https://api.openai.com/v1</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>其中：</p><ul><li><code>OPENAI_API_KEY</code> 用于身份认证。</li><li><code>OPENAI_BASE_URL</code> 用于指定接口地址。</li></ul><p>如果使用国内兼容 OpenAI API 的模型，只需要替换接口地址即可，例如：</p><div class="language-env line-numbers-mode" data-highlighter="prismjs" data-ext="env"><pre><code><span class="line">OPENAI_BASE_URL=https://api.deepseek.com</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>代码中通过环境变量读取配置：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line"><span class="token keyword">import</span> os</span>
<span class="line"><span class="token keyword">from</span> dotenv <span class="token keyword">import</span> load_dotenv</span>
<span class="line"></span>
<span class="line">load_dotenv<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">api_key <span class="token operator">=</span> os<span class="token punctuation">.</span>getenv<span class="token punctuation">(</span><span class="token string">&quot;OPENAI_API_KEY&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这样可以避免将敏感信息直接写入代码。</p><hr><h2 id="_2-5-第一次调用大模型" tabindex="-1"><a class="header-anchor" href="#_2-5-第一次调用大模型"><span>2.5 第一次调用大模型</span></a></h2><p>完成环境配置后，可以编写第一个 LangChain 程序。</p><p>创建 <code>llm.py</code>：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line"><span class="token keyword">from</span> langchain_openai <span class="token keyword">import</span> ChatOpenAI</span>
<span class="line"><span class="token keyword">import</span> os</span>
<span class="line"><span class="token keyword">from</span> dotenv <span class="token keyword">import</span> load_dotenv</span>
<span class="line"></span>
<span class="line">load_dotenv<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">llm <span class="token operator">=</span> ChatOpenAI<span class="token punctuation">(</span></span>
<span class="line">    model<span class="token operator">=</span><span class="token string">&quot;gpt-4o-mini&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    api_key<span class="token operator">=</span>os<span class="token punctuation">.</span>getenv<span class="token punctuation">(</span><span class="token string">&quot;OPENAI_API_KEY&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    base_url<span class="token operator">=</span>os<span class="token punctuation">.</span>getenv<span class="token punctuation">(</span><span class="token string">&quot;OPENAI_BASE_URL&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    temperature<span class="token operator">=</span><span class="token number">0.7</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里创建了一个 <code>ChatOpenAI</code> 对象，它负责与大模型通信。</p><p>主要参数：</p><ul><li><code>model</code>：指定使用的模型名称。</li><li><code>api_key</code>：模型服务访问密钥。</li><li><code>base_url</code>：模型服务地址。</li><li><code>temperature</code>：控制模型输出随机性。</li></ul><p>其中 temperature 是实际开发中比较常用的参数。</p><p>较低的 temperature：</p><ul><li>输出更加稳定。</li><li>适合代码生成、知识问答等场景。</li></ul><p>较高的 temperature：</p><ul><li>输出更加多样。</li><li>适合创意写作、内容生成等场景。</li></ul><hr><p>创建测试文件：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line"><span class="token keyword">from</span> llm <span class="token keyword">import</span> llm</span>
<span class="line"></span>
<span class="line">response <span class="token operator">=</span> llm<span class="token punctuation">.</span>invoke<span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">&quot;什么是LangChain？&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>response<span class="token punctuation">.</span>content<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>运行：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">python test.py</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>模型返回结果后，说明 LangChain 环境已经配置成功。</p><p>这里的调用流程为：</p><p>用户输入问题 → LangChain 封装请求 → 调用大模型 API → 返回模型生成结果。</p><hr><h2 id="_2-6-langchain-中的消息类型" tabindex="-1"><a class="header-anchor" href="#_2-6-langchain-中的消息类型"><span>2.6 LangChain 中的消息类型</span></a></h2><p>在实际开发中，LangChain 不只是简单传递字符串，而是通过消息对象描述不同角色的信息。</p><p>常见消息类型包括：</p><h3 id="systemmessage" tabindex="-1"><a class="header-anchor" href="#systemmessage"><span>SystemMessage</span></a></h3><p>用于设置模型行为。</p><p>例如：</p><p>“你是一名专业的软件工程师。”</p><h3 id="humanmessage" tabindex="-1"><a class="header-anchor" href="#humanmessage"><span>HumanMessage</span></a></h3><p>表示用户输入。</p><p>例如：</p><p>“解释一下 React Hooks。”</p><h3 id="aimessage" tabindex="-1"><a class="header-anchor" href="#aimessage"><span>AIMessage</span></a></h3><p>表示模型生成的回复。</p><p>例如：</p><p>“React Hooks 是 React 16.8 引入的特性。”</p><p>在多轮聊天场景中，通常会维护这样的消息列表：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">SystemMessage</span>
<span class="line">        ↓</span>
<span class="line">HumanMessage</span>
<span class="line">        ↓</span>
<span class="line">AIMessage</span>
<span class="line">        ↓</span>
<span class="line">HumanMessage</span>
<span class="line">        ↓</span>
<span class="line">AIMessage</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这样模型才能理解完整上下文。</p><hr><h2 id="_2-7-使用-chatprompttemplate-管理-prompt" tabindex="-1"><a class="header-anchor" href="#_2-7-使用-chatprompttemplate-管理-prompt"><span>2.7 使用 ChatPromptTemplate 管理 Prompt</span></a></h2><p>实际项目中不建议直接拼接字符串，而应该使用 Prompt 模板。</p><p>创建 <code>prompt.py</code>：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line"><span class="token keyword">from</span> langchain<span class="token punctuation">.</span>prompts <span class="token keyword">import</span> ChatPromptTemplate</span>
<span class="line"></span>
<span class="line"></span>
<span class="line">prompt <span class="token operator">=</span> ChatPromptTemplate<span class="token punctuation">.</span>from_template<span class="token punctuation">(</span></span>
<span class="line">    <span class="token triple-quoted-string string">&quot;&quot;&quot;</span>
<span class="line">    你是一名专业的软件工程师。</span>
<span class="line"></span>
<span class="line">    请回答以下问题：</span>
<span class="line">    {question}</span>
<span class="line">    &quot;&quot;&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>调用：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">message <span class="token operator">=</span> prompt<span class="token punctuation">.</span>invoke<span class="token punctuation">(</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token string">&quot;question&quot;</span><span class="token punctuation">:</span> <span class="token string">&quot;什么是FastAPI&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这样可以将 Prompt 和业务逻辑分离。</p><p>例如企业项目中：</p><ul><li>产品人员可以调整 Prompt。</li><li>开发人员维护代码逻辑。</li><li>不同业务场景可以复用模板。</li></ul><hr><h2 id="_2-8-使用-lcel-组合第一个-chain" tabindex="-1"><a class="header-anchor" href="#_2-8-使用-lcel-组合第一个-chain"><span>2.8 使用 LCEL 组合第一个 Chain</span></a></h2><p>LangChain 推荐使用 LCEL（LangChain Expression Language）构建流程。</p><p>LCEL 允许通过 <code>|</code> 操作符连接多个组件。</p><p>例如：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">chain <span class="token operator">=</span> prompt <span class="token operator">|</span> llm</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>表示：</p><p>Prompt 模板的输出作为模型输入。</p><p>完整调用：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">result <span class="token operator">=</span> chain<span class="token punctuation">.</span>invoke<span class="token punctuation">(</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token string">&quot;question&quot;</span><span class="token punctuation">:</span> <span class="token string">&quot;介绍一下Vue3&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>result<span class="token punctuation">.</span>content<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>此时执行流程：</p><p>用户输入问题 → Prompt 模板格式化 → 调用模型 → 返回结果。</p><p>相比手动编写调用逻辑，Chain 可以让多个步骤更加清晰，也方便后续加入检索、工具调用等功能。</p><hr><h2 id="_2-9-langchain-开发中的基本调试方式" tabindex="-1"><a class="header-anchor" href="#_2-9-langchain-开发中的基本调试方式"><span>2.9 LangChain 开发中的基本调试方式</span></a></h2><p>AI 应用开发与传统后端开发不同，模型输出具有一定的不确定性，因此调试重点不仅是代码是否运行，还包括 Prompt 和模型响应是否符合预期。</p><p>常见调试方式：</p><h3 id="查看-prompt-内容" tabindex="-1"><a class="header-anchor" href="#查看-prompt-内容"><span>查看 Prompt 内容</span></a></h3><p>确认发送给模型的实际内容是否正确。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="调整模型参数" tabindex="-1"><a class="header-anchor" href="#调整模型参数"><span>调整模型参数</span></a></h3><p>例如修改：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">temperature<span class="token operator">=</span><span class="token number">0.2</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>观察输出变化。</p><h3 id="保存模型输入输出日志" tabindex="-1"><a class="header-anchor" href="#保存模型输入输出日志"><span>保存模型输入输出日志</span></a></h3><p>实际生产环境通常需要记录：</p><ul><li>用户问题。</li><li>使用模型。</li><li>Prompt 内容。</li><li>模型响应时间。</li><li>Token 消耗。</li></ul><p>方便后续优化成本和效果。</p><hr><h2 id="_2-10-本章总结" tabindex="-1"><a class="header-anchor" href="#_2-10-本章总结"><span>2.10 本章总结</span></a></h2><p>本章完成了 LangChain 开发环境搭建，并了解了基础调用流程。</p><p>需要掌握以下内容：</p><ol><li>LangChain 项目通常基于 Python 环境开发，可以使用 venv、Conda 或 uv 管理依赖。</li><li>LangChain 本身不提供模型，需要连接 OpenAI、DeepSeek 等大语言模型服务。</li><li><code>ChatOpenAI</code> 用于初始化模型，<code>PromptTemplate</code> 用于管理提示词。</li><li>LCEL 可以将 Prompt、模型以及其他组件组合成 Chain。</li><li>实际 AI 应用开发中，需要将 FastAPI、LangChain、数据库和模型服务进行分层设计。</li></ol><p>下一章将进入 <strong>第三章 LangChain 核心组件</strong>，详细介绍 Model、Prompt、Output Parser、Chain、Runnable 等核心概念，并结合 Python 代码说明实际使用方式。</p><h1 id="第三章-langchain-核心组件" tabindex="-1"><a class="header-anchor" href="#第三章-langchain-核心组件"><span>第三章 LangChain 核心组件</span></a></h1><h2 id="_3-1-model-模型调用" tabindex="-1"><a class="header-anchor" href="#_3-1-model-模型调用"><span>3.1 Model（模型调用）</span></a></h2><p>Model 是 LangChain 中最基础的组件之一，负责与大语言模型进行交互。在传统开发中，不同模型服务商通常提供不同的调用方式，例如 OpenAI、Anthropic、Google 以及国内大模型厂商都有自己的 SDK 和接口规范。LangChain 通过统一的模型接口对这些服务进行了封装，使开发者可以使用类似的方式调用不同模型。</p><p>在 LangChain 中，模型主要分为两类：</p><ul><li>LLM（Large Language Model）：主要用于文本补全类型模型。</li><li>ChatModel：主要用于聊天类型模型，也是目前实际项目中更常使用的方式。</li></ul><p>目前主流的大语言模型大多属于 ChatModel，例如 GPT-4、Claude、Gemini 等。</p><hr><h3 id="_3-1-1-chatmodel-基础使用" tabindex="-1"><a class="header-anchor" href="#_3-1-1-chatmodel-基础使用"><span>3.1.1 ChatModel 基础使用</span></a></h3><p>以 OpenAI 兼容模型为例：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line"><span class="token keyword">from</span> langchain_openai <span class="token keyword">import</span> ChatOpenAI</span>
<span class="line"></span>
<span class="line">llm <span class="token operator">=</span> ChatOpenAI<span class="token punctuation">(</span></span>
<span class="line">    model<span class="token operator">=</span><span class="token string">&quot;gpt-4o-mini&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    temperature<span class="token operator">=</span><span class="token number">0.3</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">response <span class="token operator">=</span> llm<span class="token punctuation">.</span>invoke<span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">&quot;解释一下什么是FastAPI&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>response<span class="token punctuation">.</span>content<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>invoke()</code> 是 LangChain 中最基础的调用方法，用于向模型发送输入并获取结果。</p><p>返回结果通常是一个 <code>AIMessage</code> 对象，而不是普通字符串：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">response<span class="token punctuation">.</span>content</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>可以获取模型实际生成的文本内容。</p><hr><h3 id="_3-1-2-模型参数配置" tabindex="-1"><a class="header-anchor" href="#_3-1-2-模型参数配置"><span>3.1.2 模型参数配置</span></a></h3><p>实际开发中，需要根据业务场景调整模型参数。model指定使用的大语言模型。</p><p>例如：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">model<span class="token operator">=</span><span class="token string">&quot;gpt-4o-mini&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>不同模型在能力、速度以及成本方面存在差异：</p><ul><li>大模型通常理解能力更强，但调用成本更高。</li><li>小模型响应速度更快，适合简单任务。</li></ul><p>在企业项目中，通常会根据任务复杂度选择不同模型，例如：</p><ul><li>简单文本分类使用轻量模型。</li><li>复杂推理使用能力更强的模型。</li></ul><p>temperature 用于控制模型输出的随机程度。例如：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">temperature<span class="token operator">=</span><span class="token number">0.2</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>较低的 temperature 会让模型输出更加稳定，适合：</p><ul><li>技术问答。</li><li>代码生成。</li><li>数据分析。</li></ul><p>较高的 temperature 会增加输出多样性，适合：</p><ul><li>创意写作。</li><li>文案生成。</li><li>内容 brainstorming。</li></ul><p>实际项目中通常不会设置过高，否则可能导致回答不稳定。</p><hr><p>max_tokens用于限制模型最大输出长度。例如：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">max_tokens<span class="token operator">=</span><span class="token number">1000</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>主要作用：</p><ul><li>控制响应内容长度。</li><li>降低 Token 消耗。</li><li>防止模型生成过长内容。</li></ul><hr><h3 id="_3-1-3-多模型切换" tabindex="-1"><a class="header-anchor" href="#_3-1-3-多模型切换"><span>3.1.3 多模型切换</span></a></h3><p>LangChain 的一个优势是统一了模型调用接口。</p><p>例如：</p><p>OpenAI：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line"><span class="token keyword">from</span> langchain_openai <span class="token keyword">import</span> ChatOpenAI</span>
<span class="line"></span>
<span class="line">llm <span class="token operator">=</span> ChatOpenAI<span class="token punctuation">(</span></span>
<span class="line">    model<span class="token operator">=</span><span class="token string">&quot;gpt-4o-mini&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>DeepSeek：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line"><span class="token keyword">from</span> langchain_openai <span class="token keyword">import</span> ChatOpenAI</span>
<span class="line"></span>
<span class="line">llm <span class="token operator">=</span> ChatOpenAI<span class="token punctuation">(</span></span>
<span class="line">    model<span class="token operator">=</span><span class="token string">&quot;deepseek-chat&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    base_url<span class="token operator">=</span><span class="token string">&quot;https://api.deepseek.com&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>虽然底层模型不同，但上层调用方式保持一致。</p><p>这使得企业项目可以根据成本、性能需求快速替换模型，而不需要修改大量业务代码。</p><hr><h2 id="_3-2-prompt-提示词模板" tabindex="-1"><a class="header-anchor" href="#_3-2-prompt-提示词模板"><span>3.2 Prompt（提示词模板）</span></a></h2><p>Prompt 是控制模型输出的重要方式。</p><p>大语言模型本身并不知道用户真正想要什么，它只能根据输入内容进行预测。因此，合理设计 Prompt 可以明显提升模型输出质量。</p><p>在实际项目中，不推荐直接在代码中拼接字符串，而应该使用 Prompt Template 统一管理。</p><hr><h3 id="_3-2-1-prompttemplate" tabindex="-1"><a class="header-anchor" href="#_3-2-1-prompttemplate"><span>3.2.1 PromptTemplate</span></a></h3><p>PromptTemplate 用于创建普通文本模板。</p><p>例如：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line"><span class="token keyword">from</span> langchain<span class="token punctuation">.</span>prompts <span class="token keyword">import</span> PromptTemplate</span>
<span class="line"></span>
<span class="line"></span>
<span class="line">prompt <span class="token operator">=</span> PromptTemplate<span class="token punctuation">.</span>from_template<span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">&quot;请介绍一下{technology}&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line">message <span class="token operator">=</span> prompt<span class="token punctuation">.</span>invoke<span class="token punctuation">(</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token string">&quot;technology&quot;</span><span class="token punctuation">:</span><span class="token string">&quot;React&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>message<span class="token punctuation">.</span>text<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>运行时，模板中的变量会被动态替换。</p><p>这种方式适用于：</p><ul><li>单轮文本生成。</li><li>内容总结。</li><li>文案生成。</li></ul><hr><h3 id="_3-2-2-chatprompttemplate" tabindex="-1"><a class="header-anchor" href="#_3-2-2-chatprompttemplate"><span>3.2.2 ChatPromptTemplate</span></a></h3><p>在聊天模型中，更推荐使用 ChatPromptTemplate。</p><p>它可以区分不同角色的信息：</p><ul><li>System：定义模型行为。</li><li>Human：用户输入。</li><li>AI：模型回复。</li></ul><p>例如：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line"><span class="token keyword">from</span> langchain<span class="token punctuation">.</span>prompts <span class="token keyword">import</span> ChatPromptTemplate</span>
<span class="line"></span>
<span class="line"></span>
<span class="line">prompt <span class="token operator">=</span> ChatPromptTemplate<span class="token punctuation">.</span>from_messages<span class="token punctuation">(</span></span>
<span class="line">    <span class="token punctuation">[</span></span>
<span class="line">        <span class="token punctuation">(</span></span>
<span class="line">            <span class="token string">&quot;system&quot;</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">&quot;你是一名专业的软件工程师&quot;</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">(</span></span>
<span class="line">            <span class="token string">&quot;human&quot;</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">&quot;{question}&quot;</span></span>
<span class="line">        <span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">]</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>调用：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">message <span class="token operator">=</span> prompt<span class="token punctuation">.</span>invoke<span class="token punctuation">(</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token string">&quot;question&quot;</span><span class="token punctuation">:</span><span class="token string">&quot;解释一下Vue3响应式原理&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>最终发送给模型的信息类似：</p><p>系统：</p><p>你是一名专业的软件工程师。</p><p>用户：</p><p>解释一下 Vue3 响应式原理。</p><p>这种结构更符合现代聊天模型的调用方式。</p><hr><h3 id="_3-2-3-few-shot-prompt" tabindex="-1"><a class="header-anchor" href="#_3-2-3-few-shot-prompt"><span>3.2.3 Few Shot Prompt</span></a></h3><p>Few Shot Prompt 是通过提供示例，让模型学习输出格式。</p><p>例如：</p><p>希望模型按照 JSON 格式输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">示例：</span>
<span class="line"></span>
<span class="line">输入：</span>
<span class="line">React</span>
<span class="line"></span>
<span class="line">输出：</span>
<span class="line">{</span>
<span class="line">  &quot;type&quot;:&quot;frontend&quot;,</span>
<span class="line">  &quot;language&quot;:&quot;JavaScript&quot;</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>然后输入新的内容：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">Vue</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>模型会参考示例生成类似结构。</p><p>这种方式适用于：</p><ul><li>信息抽取。</li><li>分类任务。</li><li>固定格式输出。</li></ul><hr><h2 id="_3-3-output-parser-输出解析" tabindex="-1"><a class="header-anchor" href="#_3-3-output-parser-输出解析"><span>3.3 Output Parser（输出解析）</span></a></h2><p>大模型默认返回的是自然语言文本，但是实际业务通常需要结构化数据。</p><p>例如：</p><p>用户输入简历后，希望模型返回：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;score&quot;</span><span class="token operator">:</span><span class="token number">85</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;suggestions&quot;</span><span class="token operator">:</span><span class="token punctuation">[</span></span>
<span class="line">    <span class="token string">&quot;优化项目描述&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token string">&quot;补充技术细节&quot;</span></span>
<span class="line">  <span class="token punctuation">]</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这时就需要 Output Parser 对模型输出进行解析。</p><hr><h3 id="_3-3-1-stroutputparser" tabindex="-1"><a class="header-anchor" href="#_3-3-1-stroutputparser"><span>3.3.1 StrOutputParser</span></a></h3><p>最简单的解析方式是将模型输出转换为字符串。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line"><span class="token keyword">from</span> langchain_core<span class="token punctuation">.</span>output_parsers <span class="token keyword">import</span> StrOutputParser</span>
<span class="line"></span>
<span class="line"></span>
<span class="line">parser <span class="token operator">=</span> StrOutputParser<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">chain <span class="token operator">=</span> prompt <span class="token operator">|</span> llm <span class="token operator">|</span> parser</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>执行后：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">result <span class="token operator">=</span> chain<span class="token punctuation">.</span>invoke<span class="token punctuation">(</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token string">&quot;question&quot;</span><span class="token punctuation">:</span><span class="token string">&quot;介绍一下FastAPI&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>返回：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">FastAPI是一款现代化Python Web框架...</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><hr><h3 id="_3-3-2-json-输出解析" tabindex="-1"><a class="header-anchor" href="#_3-3-2-json-输出解析"><span>3.3.2 JSON 输出解析</span></a></h3><p>在实际开发中，经常需要让模型返回固定结构。</p><p>例如：</p><p>用户：</p><p>分析下面的技术能力：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">React</span>
<span class="line">Vue</span>
<span class="line">FastAPI</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>希望返回：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code><span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;frontend&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">        <span class="token string">&quot;React&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;Vue&quot;</span></span>
<span class="line">    <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;backend&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">        <span class="token string">&quot;FastAPI&quot;</span></span>
<span class="line">    <span class="token punctuation">]</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>可以使用结构化输出。</p><p>示例：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line"><span class="token keyword">from</span> pydantic <span class="token keyword">import</span> BaseModel</span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">Skill</span><span class="token punctuation">(</span>BaseModel<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    frontend<span class="token punctuation">:</span><span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">]</span></span>
<span class="line">    backend<span class="token punctuation">:</span><span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line">structured_llm <span class="token operator">=</span> llm<span class="token punctuation">.</span>with_structured_output<span class="token punctuation">(</span></span>
<span class="line">    Skill</span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这样模型输出会自动转换为 Python 对象。</p><p>在企业项目中，这种方式非常常见，例如：</p><ul><li>AI 简历分析。</li><li>AI 数据抽取。</li><li>AI 内容审核。</li></ul><hr><h2 id="_3-4-lcel-langchain-expression-language" tabindex="-1"><a class="header-anchor" href="#_3-4-lcel-langchain-expression-language"><span>3.4 LCEL（LangChain Expression Language）</span></a></h2><p>LCEL 是 LangChain 推荐的链式表达方式，用于组合不同 Runnable 组件。</p><p>它的核心思想是：</p><blockquote><p>将每一个处理步骤看作一个独立组件，然后通过组合形成完整流程。</p></blockquote><p>例如：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">chain <span class="token operator">=</span> prompt <span class="token operator">|</span> llm <span class="token operator">|</span> parser</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>表示：</p><p>Prompt 处理输入 → 模型生成内容 → Parser 格式化结果。</p><hr><h3 id="_3-4-1-runnable" tabindex="-1"><a class="header-anchor" href="#_3-4-1-runnable"><span>3.4.1 Runnable</span></a></h3><p>Runnable 是 LCEL 的基础接口。</p><p>LangChain 中很多组件都实现了 Runnable，例如：</p><ul><li>ChatModel。</li><li>PromptTemplate。</li><li>OutputParser。</li><li>Retriever。</li></ul><p>因此它们可以自由组合。</p><p>例如：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">prompt</span>
<span class="line"></span>
<span class="line">↓</span>
<span class="line"></span>
<span class="line">llm</span>
<span class="line"></span>
<span class="line">↓</span>
<span class="line"></span>
<span class="line">parser</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>每一步都可以独立替换。</p><hr><h2 id="_3-4-2-chain-调用方式" tabindex="-1"><a class="header-anchor" href="#_3-4-2-chain-调用方式"><span>3.4.2 Chain 调用方式</span></a></h2><p>LCEL 支持几种常见调用方式。</p><h3 id="invoke" tabindex="-1"><a class="header-anchor" href="#invoke"><span>invoke</span></a></h3><p>同步调用：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">result <span class="token operator">=</span> chain<span class="token punctuation">.</span>invoke<span class="token punctuation">(</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token string">&quot;question&quot;</span><span class="token punctuation">:</span><span class="token string">&quot;什么是React&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>适合普通接口请求。</p><hr><h3 id="batch" tabindex="-1"><a class="header-anchor" href="#batch"><span>batch</span></a></h3><p>批量调用：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line">results <span class="token operator">=</span> chain<span class="token punctuation">.</span>batch<span class="token punctuation">(</span></span>
<span class="line">    <span class="token punctuation">[</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">            <span class="token string">&quot;question&quot;</span><span class="token punctuation">:</span><span class="token string">&quot;介绍Vue&quot;</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">            <span class="token string">&quot;question&quot;</span><span class="token punctuation">:</span><span class="token string">&quot;介绍React&quot;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">]</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>适合批量处理任务。</p><p>例如：</p><ul><li>批量分析简历。</li><li>批量总结文章。</li></ul><hr><h3 id="stream" tabindex="-1"><a class="header-anchor" href="#stream"><span>stream</span></a></h3><p>流式输出：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line"><span class="token keyword">for</span> chunk <span class="token keyword">in</span> chain<span class="token punctuation">.</span>stream<span class="token punctuation">(</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token string">&quot;question&quot;</span><span class="token punctuation">:</span><span class="token string">&quot;介绍FastAPI&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token keyword">print</span><span class="token punctuation">(</span>chunk<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>适合聊天机器人场景。</p><p>用户可以像 ChatGPT 一样实时看到模型生成过程。</p><hr><h2 id="_3-5-一个完整-chain-示例" tabindex="-1"><a class="header-anchor" href="#_3-5-一个完整-chain-示例"><span>3.5 一个完整 Chain 示例</span></a></h2><p>前面介绍了多个组件，现在组合一个简单流程：</p><p>需求：</p><p>用户输入技术问题，AI 返回专业解释。</p><p>流程：</p><p>用户问题 → Prompt 模板 → 大模型 → 输出解析。</p><p>代码：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code><span class="line"><span class="token keyword">from</span> langchain_openai <span class="token keyword">import</span> ChatOpenAI</span>
<span class="line"><span class="token keyword">from</span> langchain<span class="token punctuation">.</span>prompts <span class="token keyword">import</span> ChatPromptTemplate</span>
<span class="line"><span class="token keyword">from</span> langchain_core<span class="token punctuation">.</span>output_parsers <span class="token keyword">import</span> StrOutputParser</span>
<span class="line"></span>
<span class="line"></span>
<span class="line">llm <span class="token operator">=</span> ChatOpenAI<span class="token punctuation">(</span></span>
<span class="line">    model<span class="token operator">=</span><span class="token string">&quot;gpt-4o-mini&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line">prompt <span class="token operator">=</span> ChatPromptTemplate<span class="token punctuation">.</span>from_template<span class="token punctuation">(</span></span>
<span class="line">    <span class="token triple-quoted-string string">&quot;&quot;&quot;</span>
<span class="line">    你是一名高级前端工程师。</span>
<span class="line"></span>
<span class="line">    请回答：</span>
<span class="line">    {question}</span>
<span class="line">    &quot;&quot;&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line">parser <span class="token operator">=</span> StrOutputParser<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line">chain <span class="token operator">=</span> prompt <span class="token operator">|</span> llm <span class="token operator">|</span> parser</span>
<span class="line"></span>
<span class="line"></span>
<span class="line">result <span class="token operator">=</span> chain<span class="token punctuation">.</span>invoke<span class="token punctuation">(</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token string">&quot;question&quot;</span><span class="token punctuation">:</span><span class="token string">&quot;Vue3的响应式原理是什么&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>result<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个流程已经具备实际 AI 应用的基本结构：</p><ul><li>Prompt 负责控制输入。</li><li>Model 负责生成内容。</li><li>Parser 负责处理输出。</li><li>Chain 负责组织执行流程。</li></ul><p>后续的 RAG、Agent 本质上也是在这个基础上继续扩展。</p><hr><h2 id="_3-6-本章总结" tabindex="-1"><a class="header-anchor" href="#_3-6-本章总结"><span>3.6 本章总结</span></a></h2><p>本章介绍了 LangChain 最核心的基础组件。</p><p>需要掌握：</p><ol><li>Model 负责统一调用不同的大语言模型。</li><li>Prompt Template 用于管理和优化模型输入。</li><li>Output Parser 用于将模型输出转换为业务需要的数据格式。</li><li>LCEL 可以将多个组件组合成完整处理链。</li><li>Runnable 是 LangChain 组件组合的基础。</li><li>实际项目中的 AI 功能通常都是多个组件组合，而不是单独调用模型。</li></ol><p>下一章将进入 <strong>第四章 对话系统开发</strong>，重点介绍多轮聊天、Message 管理、Memory、Chat History 以及 FastAPI 中如何实现类似 ChatGPT 的流式对话接口。</p>`,428)])])}const r=s(i,[["render",p]]),d=JSON.parse('{"path":"/posts/ailearning/Langchain%E5%85%A5%E9%97%A8%E6%8C%87%E5%8D%97.html","title":"LangChain 基础","lang":"zh-CN","frontmatter":{"date":"2026-08-15T00:00:00.000Z","category":["说明文档"],"tag":["大模型基础"]},"headers":[{"level":2,"title":"1.1 什么是 LangChain","slug":"_1-1-什么是-langchain","link":"#_1-1-什么是-langchain","children":[]},{"level":2,"title":"1.2 为什么需要 LangChain","slug":"_1-2-为什么需要-langchain","link":"#_1-2-为什么需要-langchain","children":[]},{"level":2,"title":"1.3 LangChain 在 AI 应用开发中的位置","slug":"_1-3-langchain-在-ai-应用开发中的位置","link":"#_1-3-langchain-在-ai-应用开发中的位置","children":[]},{"level":2,"title":"1.4 LangChain 核心组成","slug":"_1-4-langchain-核心组成","link":"#_1-4-langchain-核心组成","children":[{"level":3,"title":"1.4.1 Model（模型）","slug":"_1-4-1-model-模型","link":"#_1-4-1-model-模型","children":[]},{"level":3,"title":"1.4.2 Prompt（提示词）","slug":"_1-4-2-prompt-提示词","link":"#_1-4-2-prompt-提示词","children":[]},{"level":3,"title":"1.4.3 Chain（链）","slug":"_1-4-3-chain-链","link":"#_1-4-3-chain-链","children":[]},{"level":3,"title":"1.4.4 Retriever（检索器）","slug":"_1-4-4-retriever-检索器","link":"#_1-4-4-retriever-检索器","children":[]},{"level":3,"title":"1.4.5 Agent（智能代理）","slug":"_1-4-5-agent-智能代理","link":"#_1-4-5-agent-智能代理","children":[]}]},{"level":2,"title":"1.5 LangChain 与大模型 API 的关系","slug":"_1-5-langchain-与大模型-api-的关系","link":"#_1-5-langchain-与大模型-api-的关系","children":[]},{"level":2,"title":"1.6 本章总结","slug":"_1-6-本章总结","link":"#_1-6-本章总结","children":[]},{"level":2,"title":"2.1 Python 环境准备","slug":"_2-1-python-环境准备","link":"#_2-1-python-环境准备","children":[]},{"level":2,"title":"2.2 创建 LangChain 项目","slug":"_2-2-创建-langchain-项目","link":"#_2-2-创建-langchain-项目","children":[]},{"level":2,"title":"2.3 安装 LangChain 相关依赖","slug":"_2-3-安装-langchain-相关依赖","link":"#_2-3-安装-langchain-相关依赖","children":[]},{"level":2,"title":"2.4 配置大模型 API","slug":"_2-4-配置大模型-api","link":"#_2-4-配置大模型-api","children":[]},{"level":2,"title":"2.5 第一次调用大模型","slug":"_2-5-第一次调用大模型","link":"#_2-5-第一次调用大模型","children":[]},{"level":2,"title":"2.6 LangChain 中的消息类型","slug":"_2-6-langchain-中的消息类型","link":"#_2-6-langchain-中的消息类型","children":[{"level":3,"title":"SystemMessage","slug":"systemmessage","link":"#systemmessage","children":[]},{"level":3,"title":"HumanMessage","slug":"humanmessage","link":"#humanmessage","children":[]},{"level":3,"title":"AIMessage","slug":"aimessage","link":"#aimessage","children":[]}]},{"level":2,"title":"2.7 使用 ChatPromptTemplate 管理 Prompt","slug":"_2-7-使用-chatprompttemplate-管理-prompt","link":"#_2-7-使用-chatprompttemplate-管理-prompt","children":[]},{"level":2,"title":"2.8 使用 LCEL 组合第一个 Chain","slug":"_2-8-使用-lcel-组合第一个-chain","link":"#_2-8-使用-lcel-组合第一个-chain","children":[]},{"level":2,"title":"2.9 LangChain 开发中的基本调试方式","slug":"_2-9-langchain-开发中的基本调试方式","link":"#_2-9-langchain-开发中的基本调试方式","children":[{"level":3,"title":"查看 Prompt 内容","slug":"查看-prompt-内容","link":"#查看-prompt-内容","children":[]},{"level":3,"title":"调整模型参数","slug":"调整模型参数","link":"#调整模型参数","children":[]},{"level":3,"title":"保存模型输入输出日志","slug":"保存模型输入输出日志","link":"#保存模型输入输出日志","children":[]}]},{"level":2,"title":"2.10 本章总结","slug":"_2-10-本章总结","link":"#_2-10-本章总结","children":[]},{"level":2,"title":"3.1 Model（模型调用）","slug":"_3-1-model-模型调用","link":"#_3-1-model-模型调用","children":[{"level":3,"title":"3.1.1 ChatModel 基础使用","slug":"_3-1-1-chatmodel-基础使用","link":"#_3-1-1-chatmodel-基础使用","children":[]},{"level":3,"title":"3.1.2 模型参数配置","slug":"_3-1-2-模型参数配置","link":"#_3-1-2-模型参数配置","children":[]},{"level":3,"title":"3.1.3 多模型切换","slug":"_3-1-3-多模型切换","link":"#_3-1-3-多模型切换","children":[]}]},{"level":2,"title":"3.2 Prompt（提示词模板）","slug":"_3-2-prompt-提示词模板","link":"#_3-2-prompt-提示词模板","children":[{"level":3,"title":"3.2.1 PromptTemplate","slug":"_3-2-1-prompttemplate","link":"#_3-2-1-prompttemplate","children":[]},{"level":3,"title":"3.2.2 ChatPromptTemplate","slug":"_3-2-2-chatprompttemplate","link":"#_3-2-2-chatprompttemplate","children":[]},{"level":3,"title":"3.2.3 Few Shot Prompt","slug":"_3-2-3-few-shot-prompt","link":"#_3-2-3-few-shot-prompt","children":[]}]},{"level":2,"title":"3.3 Output Parser（输出解析）","slug":"_3-3-output-parser-输出解析","link":"#_3-3-output-parser-输出解析","children":[{"level":3,"title":"3.3.1 StrOutputParser","slug":"_3-3-1-stroutputparser","link":"#_3-3-1-stroutputparser","children":[]},{"level":3,"title":"3.3.2 JSON 输出解析","slug":"_3-3-2-json-输出解析","link":"#_3-3-2-json-输出解析","children":[]}]},{"level":2,"title":"3.4 LCEL（LangChain Expression Language）","slug":"_3-4-lcel-langchain-expression-language","link":"#_3-4-lcel-langchain-expression-language","children":[{"level":3,"title":"3.4.1 Runnable","slug":"_3-4-1-runnable","link":"#_3-4-1-runnable","children":[]}]},{"level":2,"title":"3.4.2 Chain 调用方式","slug":"_3-4-2-chain-调用方式","link":"#_3-4-2-chain-调用方式","children":[{"level":3,"title":"invoke","slug":"invoke","link":"#invoke","children":[]},{"level":3,"title":"batch","slug":"batch","link":"#batch","children":[]},{"level":3,"title":"stream","slug":"stream","link":"#stream","children":[]}]},{"level":2,"title":"3.5 一个完整 Chain 示例","slug":"_3-5-一个完整-chain-示例","link":"#_3-5-一个完整-chain-示例","children":[]},{"level":2,"title":"3.6 本章总结","slug":"_3-6-本章总结","link":"#_3-6-本章总结","children":[]}],"git":{"updatedTime":1786811196000,"contributors":[{"name":"ksldnasx","username":"ksldnasx","email":"wh8261408@126.com","commits":1,"url":"https://github.com/ksldnasx"},{"name":"ksladnasx","username":"ksladnasx","email":"146323705+ksladnasx@users.noreply.github.com","commits":1,"url":"https://github.com/ksladnasx"}],"changelog":[{"hash":"f419c0e4f62227a02899cae80091ea2f29a7ee99","time":1786811196000,"email":"146323705+ksladnasx@users.noreply.github.com","author":"Wagver","message":"docs: 更新 LangChain 基础"},{"hash":"1a96106d5a23834d512cbe71de89c171dea14631","time":1786721096000,"email":"wh8261408@126.com","author":"ksldnasx","message":"feat"}]},"filePathRelative":"posts/ailearning/Langchain入门指南.md","excerpt":"\\n<h2>1.1 什么是 LangChain</h2>\\n<p>随着大语言模型（Large Language Model，LLM）的快速发展，越来越多的软件系统开始接入 AI 能力，例如智能客服、企业知识库、AI 助手、自动化办公工具等。但是，大语言模型本身只负责理解用户输入并生成文本，它并不了解企业内部数据，也无法直接访问数据库、调用业务接口或执行具体任务。</p>\\n<p>例如，一个企业希望开发一个内部知识库问答系统，员工询问“公司的报销流程是什么”。如果直接调用大模型，模型并不知道企业自己的规章制度，因此无法给出准确答案。要解决这个问题，需要在用户问题和大模型之间增加一层应用逻辑，将企业数据、业务工具以及模型能力结合起来。</p>"}');export{r as comp,d as data};
